CREATE TEMPORARY VIEW winner_model_${grass_region_without_quote} AS
SELECT
     cspu_id
    ,model_id
    ,item_id
    ,shop_id
    ,bid_price/100000 as bid_price
    ,full_start_timestamp
    ,if(decay_start_timestamp=0,null,decay_start_timestamp) as decay_start_timestamp
    ,if(no_boost_start_timestamp=0,null,no_boost_start_timestamp) as no_boost_start_timestamp
    ,if(no_boost_start_timestamp=0,
      (unix_timestamp(to_timestamp(date_timezone_convert(${regional_date},${regional_hour},'SG','SG','yyyy-MM-dd HH'),'yyyy-MM-dd HH'))+(${regional_minute} * 60)-full_start_timestamp)/3600,
      (no_boost_start_timestamp-full_start_timestamp)/3600
      ) as last_win_accumulative_hours
    ,case
        when status ='full_traffic_boost'  then 1
        when status ='decay_traffic_boost' then 2
     end as traffic_status
from paimon.rcmd_feature.ods_sr_data_warehouse_tc_pb_winner_model
where grass_region in (${grass_region})
and status in ('full_traffic_boost','decay_traffic_boost') --only output algo needs data
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW dim_model_${grass_region_without_quote} AS
select
    model_id
   ,model_stock
from mp_item.rt_dim_model__reg_s0_live
where grass_region in (${grass_region})
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW shop_type_${grass_region_without_quote} AS
select
     shop_id
    ,type as shop_scs_type
from regds_listing.dim_scs_shop_list_df
where grass_region in (${grass_region}) and type in ('scs-local','scs-cb')
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW cspu_label_${grass_region_without_quote} AS
select
     cspu_id
    ,cspu_pr_rate
from srdi_mart.dws_sr_data_warehouse_tc_pb_cspu_level_1d
WHERE grass_region IN (${grass_region})
and local_date = data_infra.max_pt('srdi_mart.dws_sr_data_warehouse_tc_pb_cspu_level_1d', 'local_date', "grass_region=${grass_region} and local_date<${regional_date}")
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_tc_pb_winner_model_minf
PARTITION (grass_region = ${grass_region}, regional_date = ${regional_date}, regional_hour = ${regional_hour}, regional_minute=${regional_minute})
select /*+ REPARTITION(100) */
     a.cspu_id
    ,a.model_id
    ,item_id
    ,a.shop_id
    ,b.model_stock
    ,a.bid_price
    ,d.cspu_pr_rate
    ,if(c.shop_scs_type is null,'non-scs',c.shop_scs_type) as shop_scs_type
    ,case
       when traffic_status =1 then 'Normal Boost'
       when traffic_status =2 then 'Decay Boost'
       else 'No Boost'
     end current_boost_type
    ,traffic_status
    ,last_win_accumulative_hours
    ,full_start_timestamp
    ,decay_start_timestamp
    ,no_boost_start_timestamp
from winner_model_${grass_region_without_quote} a
left join dim_model_${grass_region_without_quote} b on a.model_id=b.model_id
left join shop_type_${grass_region_without_quote} c on a.shop_id=c.shop_id
left join cspu_label_${grass_region_without_quote} d on a.cspu_id=d.cspu_id
